  if(mode==='stress'&&world.centroids){const cs=rows.filter(r=>fin(mapValue(mode,r))&&world.centroids[r.iso3]).map(r=>world.centroids[r.iso3]);if(cs.length>=2){const xs=cs.map(c=>c[0]),ys=cs.map(c=>c[1]);let x0=Math.min(...xs)-70,x1=Math.max(...xs)+70,y0=Math.min(...ys)-45,y1=Math.max(...ys)+45;let w=x1-x0,h=y1-y0;if(w/h<W/H){const nw=h*W/H;x0-=(nw-w)/2;w=nw;}else{const nh=w*H/W;y0-=(nh-h)/2;h=nh;}if(w<W*0.7){vb=[x0,y0,w,h];k=W/w;}}}
