 const mode=CDS.mapMode||'cds',nStress=all.filter(r=>r.stress).length,nFund=all.filter(r=>r.fund).length,nRating=all.filter(r=>r.rating&&r.rating.consensus).length,nPdebt=all.filter(r=>r.pdebt).length;
 byId('cdsdesk-map-tag').textContent=mode==='cds'?`5Y CDS · ${all.filter(r=>r.status==='liquid'||r.status==='thin').length} priced · ${all.filter(r=>r.status==='unpriced').length} either/or · ${all.filter(r=>r.status==='not_in_tape').length} known issuers with no public print · click a country for history`:mode==='stress'?`ECB stress · ${nStress} countries with their own ECB record (SovCISS sovereign · CISS systemic · CLIFS monthly) · click a country for its own 2006 → chart`:mode==='rating'?`ESMA consensus rating · ${nRating} of ${all.length} known issuers · hover for every agency, click a country for history`:mode==='pdebt'?`IMF Global Debt Database · private debt / GDP · ${nPdebt} of ${all.length} known issuers`:`IMF World Economic Outlook · ${nFund} of ${all.length} known issuers · click a country for history`;
 byId('cdsdesk-map-ctl').innerHTML=MAP_MODES.map(([k,lab])=>`<button type="button" class="seg-btn${k===mode?' active':''}" data-map-mode="${k}"${k==='stress'&&!nStress?' disabled title="history file not loaded yet"':''}>${lab}${k==='stress'&&nStress?` <span class="t-mute">· ${nStress}</span>`:k==='rating'&&nRating?` <span class="t-mute">· ${nRating}</span>`:k==='pdebt'&&nPdebt?` <span class="t-mute">· ${nPdebt}</span>`:(k==='debt'||k==='fiscal')&&nFund?` <span class="t-mute">· ${nFund}</span>`:''}</button>`).join('');
