 byId(`cdsdesk-${prefix}-tag`).textContent=`${all.length} names in the tape · ${nP} priced (${nL} liquid) · ${nU} either/or · ${nD} dormant · median ${bp(g.median_bp)}bp · showing ${rows.length}`;
